// Üretilen dosya: tool/ozgun/uret.py. Kimya · Gazlar ve gaz yasaları hesapları (zor).
const ozChemistry10Zor = <(String, String, List<String>, String)>[
  ('Cıvanın yoğunluğu 13 600 kg/m³ ve g = 9,8 m/s² alınırsa 76 cm yüksekliğindeki cıva sütununun tabanına yaptığı basınç yaklaşık kaç Pa\'dır?', '1,01·10⁵', ['9,8·10³', '1,36·10⁴', '1,013·10⁷'], 'P = h·d·g = 0,76 × 13 600 × 9,8 ≈ 101 300 Pa, yani yaklaşık 1,01·10⁵ Pa\'dır.'),
  ('Yatay duran bir ucu kapalı boruda 19 cm\'lik cıva sütunuyla 20 cm boyunda hava hapsedilmiştir. Boru açık ucu yukarı gelecek biçimde düşey konuma getirilirse sıcaklık sabitken hava sütununun boyu kaç cm olur? (Açık hava basıncı 76 cmHg)', '16', ['25,5', '19', '15'], 'Yatayda P = 76 cmHg; düşeyde P = 76 + 19 = 95 cmHg olur. Boyle yasasına göre 76 × 20 = 95 × L, L = 16 cm.'),
  ('Sabit hacimli bir lastiğin göstergesi 27 °C\'de 2,0 atm okuyor. Uzun yolculuktan sonra lastik havası 57 °C\'ye çıkıyorsa gösterge kaç atm okur? (Açık hava basıncı 1,0 atm)', '2,3', ['2,25', '3,3', '4,1'], 'Gaz yasasında mutlak basınç kullanılır: 3,0 atm × 330/300 = 3,3 atm. Gösterge bundan 1 atm eksik, yani 2,3 atm okur.'),
  ('Gazların basıncını taneciklerin çeperlere çarpmasıyla açıklayan ilk kinetik modeli 1738\'de \'Hydrodynamica\' adlı eserinde ortaya koyan bilim insanı kimdir?', 'Daniel Bernoulli', ['Robert Boyle', 'Amedeo Avogadro', 'Joseph Louis Gay-Lussac'], 'Daniel Bernoulli, 1738\'deki eserinde gaz basıncını hareketli taneciklerin çarpmalarıyla açıklayarak kinetik teorinin temelini atmıştır.'),
  ('Boltzmann sabiti k = 1,38·10⁻²³ J/K ise 300 K\'deki bir gaz molekülünün ortalama öteleme kinetik enerjisi (3/2)kT yaklaşık kaç J\'dür?', '6,2·10⁻²¹', ['4,1·10⁻²¹', '1,24·10⁻²⁰', '3,7·10³'], '1,5 × 1,38·10⁻²³ × 300 ≈ 6,21·10⁻²¹ J bulunur.'),
  ('Kök ortalama kare hız bağıntısı v = √(3RT/M) ile 300 K\'deki azot moleküllerinin (M = 0,028 kg/mol) hızı yaklaşık kaç m/s\'dir? (R = 8,314 J/(mol·K))', '517', ['1934', '365', '2700'], 'v = √(3 × 8,314 × 300 / 0,028) = √267 236 ≈ 517 m/s bulunur.'),
  ('Kök ortalama kare hızı açısından oksijen moleküllerinin, 300 K\'deki hidrojen moleküllerine yetişebilmesi için oksijen kaç K\'ye ısıtılmalıdır? (H₂ = 2, O₂ = 32 g/mol)', '4800', ['1200', '600', '19 200'], 'Hızların eşit olması için T/M oranı eşit olmalıdır: T = 300 × 32/2 = 4800 K.'),
  ('Bir gaz örneğinde en olası hız (vₒ), ortalama hız (v̄) ve kök ortalama kare hız (vₖₒₖ) arasındaki büyüklük sıralaması hangisidir?', 'vₒ < v̄ < vₖₒₖ', ['vₖₒₖ < v̄ < vₒ', 'v̄ < vₒ < vₖₒₖ', 'vₒ = v̄ = vₖₒₖ değeriyle eşit'], 'Maxwell-Boltzmann dağılımı sağa uzun kuyruklu olduğundan kare ortalamanın kökü en büyük, en sık görülen hız ise en küçüktür.'),
  ('Aynı sıcaklık ve basınçta, molekül çapı daha büyük olan bir gazın ortalama serbest yolu küçük çaplı bir gazınkine göre nasıldır?', 'Daha kısadır', ['Daha uzundur', 'Eşittir', 'Çapın karesiyle doğru orantılı olarak uzundur'], 'Büyük moleküllerin çarpışma kesit alanı daha büyüktür; başka moleküllerle karşılaşma olasılıkları artar ve serbest yol kısalır.'),
  ('Sabit hacimli kapalı bir kaptaki gaz ısıtılırsa moleküllerin birim zamanda yaptığı çarpışma sayısı ve ortalama serbest yol nasıl değişir?', 'Çarpışma sayısı artar, serbest yol değişmez', ['Çarpışma sayısı da serbest yol da artar', 'Çarpışma sayısı azalır, serbest yol uzar', 'Çarpışma sayısı değişmez, serbest yol kısalır'], 'Birim hacimdeki molekül sayısı sabit kaldığından serbest yol değişmez; ancak moleküller hızlandığı için bu yolu daha kısa sürede alıp daha sık çarpışırlar.'),
  ('Kinetik teoriden türetilen PV = (2/3)Eₖ bağıntısında Eₖ gazın toplam öteleme kinetik enerjisidir. 1 L\'lik bir kaptaki gazın toplam öteleme kinetik enerjisi 150 J ise basıncı kaç Pa\'dır?', '1,0·10⁵', ['1,0·10²', '2,25·10⁵', '1,5·10⁵'], 'P = (2/3) × 150 J / 10⁻³ m³ = 1,0·10⁵ Pa bulunur.'),
  ('27 °C\'deki 2 mol ideal gaz ile 327 °C\'deki 1 mol ideal gazın toplam öteleme kinetik enerjileri için ne söylenebilir?', 'Birbirine eşittir', ['Birincisininki iki katıdır', 'İkincisininki iki katıdır', 'İkincisininki dört katıdır'], 'Toplam enerji (3/2)nRT ile orantılıdır: 2 × 300 = 1 × 600 olduğundan iki örneğin toplam kinetik enerjisi eşittir.'),
  ('Sabit sıcaklıkta bir gazın basıncı 1 atm artırıldığında hacmi 6 L\'den 4 L\'ye düşüyor. Gazın ilk basıncı kaç atm\'dir?', '2', ['1', '3', '1,5'], 'P × 6 = (P + 1) × 4 eşitliğinden 2P = 4 ve P = 2 atm bulunur.'),
  ('1 L\'lik bir kaptaki 1 atm\'lik hava, her vuruşta kaba bağlanıp 1 L\'lik boş silindiri dolduran ve sonra bu silindirdeki gazı dışarı atan bir pompayla boşaltılıyor. Sıcaklık sabitse üç vuruştan sonra kaptaki basınç kaç atm olur?', '0,125', ['0,25', '0,3335', '0'], 'Her vuruşta gaz iki katı hacme yayılıp yarısı atıldığından basınç yarıya iner: 1 × (1/2)³ = 0,125 atm.'),
  ('Aynı miktardaki bir gaz için iki farklı sıcaklıkta P-V eğrileri (izotermler) çiziliyor. Yüksek sıcaklıktaki izoterm için hangisi doğrudur?', 'Eksenlerden daha uzakta yer alır', ['Eksenlere daha yakın yer alır', 'Düşük sıcaklıktaki izotermi bir noktada keser', 'Doğrusal bir biçim alır'], 'Her izotermde PV = nRT\'dir; T büyüdükçe PV çarpımı büyür ve hiperbol başlangıç noktasından uzaklaşır.'),
  ('Sabit basınçta belirli miktarda gaz için V-T(K) grafiğinde, aynı gazın daha yüksek basınçtaki doğrusu için hangisi doğrudur?', 'Eğimi daha küçüktür', ['Eğimi daha büyüktür', 'Başlangıçtan geçmez', 'Yatay eksene paralel olur'], 'V = (nR/P)·T olduğundan doğrunun eğimi nR/P\'dir; basınç büyüdükçe eğim küçülür.'),
  ('Charles ve Gay-Lussac\'ın gözlemlerinin özgün biçimine göre sabit basınçta bir gaz 1 °C ısıtıldığında hacmi ne kadar artar?', '0 °C\'deki hacminin yaklaşık 1/273\'ü kadar', ['O anki hacminin tam 1/100\'ü kadar', '0 °C\'deki hacminin yaklaşık olarak 1/373\'ü kadar', 'Her sıcaklıkta sabit olarak 1 mL kadar'], '0 °C\'den itibaren her 1 °C\'lik artış, gazın 0 °C\'deki hacminin 1/273\'ü kadar genleşme sağlar; bu yüzden hacim −273 °C\'de sıfıra uzanır.'),
  ('Sabit basınçta bir gazın mutlak sıcaklığı 100 K artırıldığında hacmi %25 artıyor. Gazın ilk sıcaklığı kaç K\'dir?', '400', ['100', '300', '125,5'], 'T₁ × 1,25 = T₁ + 100 eşitliğinden 0,25 T₁ = 100 ve T₁ = 400 K bulunur.'),
  ('Sabit hacimde gaz basıncının sıcaklıkla arttığını 1700\'lerin başında ilk gözlemleyenlerden olduğu için bu ilişkiye zaman zaman adı verilen Fransız fizikçi kimdir?', 'Guillaume Amontons', ['Blaise Pascal', 'Jacques Charles', 'Antoine Laurent Lavoisier'], 'Basınç-sıcaklık ilişkisi Gay-Lussac yasası yanında \'Amontons yasası\' olarak da anılır; Amontons bu ilişkiyi hava termometreleri üzerinde çalışırken fark etmiştir.'),
  ('Gay-Lussac\'a göre aynı koşullarda 2 hacim hidrojen 1 hacim oksijenle birleşerek 2 hacim su buharı verir. Avogadro bu gözlemi açıklamak için oksijen hakkında hangi sonuca varmıştır?', 'Oksijenin iki atomlu moleküller hâlinde bulunduğu', ['Oksijen atomlarının hidrojen atomlarından daha hafif olduğu', 'Oksijenin tek atomlu bir gaz olduğu', 'Su buharının ideal gaz olmadığı'], 'Eşit hacimler eşit sayıda tanecik içeriyorsa 1 hacim oksijenden 2 hacim su oluşması, her oksijen taneciğinin iki parçaya bölünebilen O₂ molekülü olmasını gerektirir.'),
  ('IUPAC\'ın 1982\'den bu yana kullandığı standart koşullarda (0 °C ve 1 bar) 1 mol ideal gazın hacmi yaklaşık kaç litredir?', '22,7', ['22,4', '24,5', '24,79'], '1 bar, 1 atm\'den biraz küçük olduğundan molar hacim 22,4 L yerine yaklaşık 22,7 L olur.'),
  ('Yerde 1 atm ve 27 °C\'de 10 L hacimli bir meteoroloji balonu, basıncın 0,25 atm ve sıcaklığın −33 °C olduğu yüksekliğe çıkıyor. Balon esnek ve gaz kaçırmıyorsa yeni hacmi kaç L olur?', '32', ['40', '50', '12,5'], 'V₂ = V₁ × (P₁/P₂) × (T₂/T₁) = 10 × 4 × (240/300) = 32 L bulunur.'),
  ('819 °C ve 2 atm\'de 500 mL hacim kaplayan bir gaz örneği normal koşullara (0 °C, 1 atm) getirilirse kaç mL hacim kaplar?', '250', ['1000', '125', '4000'], 'V₀ = 500 × (2/1) × (273/1092) = 250 mL bulunur; 819 °C = 1092 K\'dir.'),
  ('0 °C ve 1 atm\'de 1 L ideal gazdaki molekül sayısı (Loschmidt sayısı) yaklaşık kaçtır? (Nₐ = 6,02·10²³)', '2,7·10²²', ['6,0·10²³', '2,24·10²⁴', '1,3·10²²'], 'n = 1/22,4 ≈ 0,0446 mol; 0,0446 × 6,02·10²³ ≈ 2,7·10²² molekül bulunur.'),
  ('1 L·atm büyüklüğündeki PV çarpımı yaklaşık kaç joule enerjiye karşılık gelir?', '101,3', ['8,314', '760,0', '1,0133'], '1 L = 10⁻³ m³ ve 1 atm = 101 325 Pa olduğundan 1 L·atm = 101,3 J\'dür.'),
  ('He (4 g/mol) ve Ar (40 g/mol) gazlarından oluşan bir karışımın ortalama mol kütlesi 16 g/mol\'dür. Karışımdaki He\'nin mol kesri kaçtır?', '2/3', ['1/3', '1/2', '2/5'], '4x + 40(1 − x) = 16 eşitliğinden 36x = 24 ve x = 2/3 bulunur.'),
  ('Dumas yönteminde bir sıvının buharı, hacmi 410 mL olan bir balonu 127 °C ve 1 atm\'de doldurduğunda buharın kütlesi 1,2 g ölçülüyor. Sıvının mol kütlesi kaç g/mol\'dür? (R = 0,082 L·atm/(mol·K))', '96', ['48', '30', '192'], 'n = PV/RT = (1 × 0,41)/(0,082 × 400) = 0,0125 mol; M = 1,2/0,0125 = 96 g/mol.'),
  ('Dumas yönteminde balona ölçülmeden, gereğinden fazla uçucu sıvı konulması sonucu neden bozmaz?', 'Fazla buhar dışarı kaçar, balonda dış basınçta buhar kalır', ['Fazla sıvı balon çeperine yapışıp tartıma katılmaz', 'Fazla sıvı ısıtma sırasında kimyasal olarak bozunur', 'Balondaki havanın kütlesi bu fazlalığı tam olarak dengeler'], 'Balonun ağzı ince bir kılcalla açık bırakılır; sıvı buharlaşırken fazlası dışarı çıkar ve sonunda balon, dış basınçta ve banyo sıcaklığında yalnız buharla dolu kalır.'),
  ('Victor Meyer yönteminde uçucu bir sıvının mol kütlesi bulunurken doğrudan hangi nicelik ölçülür?', 'Buharın yerinden ettiği havanın hacmi', ['Sıvının kaynama noktasındaki yükselme', 'Buharın kap çeperlerine yaptığı basınç', 'Sıvının çözeltideki donma noktası düşmesi'], 'Tartılmış sıvı sıcak bir tüpte buharlaşınca eşit hacimde havayı dışarı iter; bu havanın hacmi ölçülerek buharın mol sayısı bulunur.'),
  ('1 g su 100 °C ve 1 atm\'de tamamen buharlaştırılırsa oluşan buhar ideal gaz kabul edildiğinde yaklaşık kaç litre hacim kaplar? (H₂O = 18 g/mol, R = 0,082 L·atm/(mol·K))', '1,7', ['22,4', '0,056', '3,4'], 'n = 1/18 ≈ 0,0556 mol; V = 0,0556 × 0,082 × 373 ≈ 1,7 L. Yaklaşık 1 mL sıvı su bu kadar buhar verir.'),
  ('Sürtünmesiz hareketli pistonlu bir kapta sabit dış basınç ve sıcaklıkta He gazı bulunuyor. Kaba bir miktar Ar eklenirse He\'nin kısmi basıncı nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar sonra eski değerine döner'], 'Toplam basınç dış basınca eşit kalırken hacim büyür; He\'nin mol kesri düştüğünden kısmi basıncı da azalır.'),
  ('Amagat\'ın kısmi hacimler yasası neyi ifade eder?', 'Karışımın hacmi, her gazın toplam basınçta tek başına kaplayacağı hacimlerin toplamıdır', ['Karışımın basıncı, her gazın hacimleri toplamına eşittir', 'Gazların hacimleri mol kütleleriyle doğru orantılıdır', 'Karışımdaki her gaz kabın yarısını doldurur'], 'Kısmi hacim, bir gazın karışımın sıcaklık ve toplam basıncında yalnız başına kaplayacağı hacimdir; bunların toplamı karışımın hacmini verir.'),
  ('27 °C\'de 1 L\'lik kapta 2 atm H₂, aynı sıcaklıkta 4 L\'lik kapta 1 atm N₂ vardır. Kaplar birleştirilip sıcaklık 127 °C\'ye çıkarılırsa toplam basınç kaç atm olur?', '1,6', ['1,25', '3,0', '2,4'], '27 °C\'de birleşmiş basınç (2 × 1 + 1 × 4)/5 = 1,2 atm; 400/300 oranıyla ısıtılınca 1,2 × 4/3 = 1,6 atm olur.'),
  ('Aynı sıcaklıkta 2 L\'lik kapta 0,4 mol He ve 3 L\'lik kapta 0,6 mol Ne vardır. Aradaki musluk açılınca kaplardan birinden diğerine net gaz akışı olur mu?', 'Olmaz, çünkü iki kaptaki basınçlar başlangıçta eşittir', ['Olur, çünkü Ne kabının hacmi daha büyüktür', 'Olur, çünkü He atomları daha hızlıdır', 'Olmaz, çünkü gazlar birbirine hiç karışmaz'], 'Her iki kapta n/V = 0,2 mol/L olduğundan basınçlar eşittir; net akış olmaz ama gazlar difüzyonla yine de birbirine karışır.'),
  ('Hacmi V olan A kabında P basınçlı X gazı, hacmi 2V olan B kabında aynı sıcaklıkta 2P basınçlı Y gazı vardır. Musluk açıldıktan sonra karışımda X\'in mol kesri kaçtır?', '1/5', ['1/3', '1/2', '2/5'], 'Mol sayıları PV ile orantılıdır: X için P·V, Y için 2P·2V = 4PV. X\'in mol kesri 1/(1 + 4) = 1/5 olur.'),
  ('27 °C\'de su üzerinde 492 mL oksijen toplanıyor ve kaptaki toplam basınç 787 mmHg ölçülüyor. 27 °C\'de suyun buhar basıncı 27 mmHg ise toplanan oksijen kaç moldür? (R = 0,082 L·atm/(mol·K))', '0,02', ['0,2', '0,0207', '0,04'], 'P(O₂) = 787 − 27 = 760 mmHg = 1 atm; n = PV/RT = (1 × 0,492)/(0,082 × 300) = 0,02 mol.'),
  ('Su üzerinde gaz toplanan ters çevrilmiş bir silindirde içerideki su seviyesi dışarıdakinden 13,6 cm yüksekte kalmıştır. Açık hava basıncı 760 mmHg ise silindirdeki gazların toplam basıncı kaç mmHg\'dir? (dsu = 1 g/cm³, dcıva = 13,6 g/cm³)', '750', ['770', '746,4', '624'], '13,6 cm su sütunu 136/13,6 = 10 mmHg\'ye denktir; içerideki su yukarıda olduğundan gaz basıncı 760 − 10 = 750 mmHg olur.'),
  ('Sabit hacim ve sıcaklıktaki bir kapta NO\'nun kısmi basıncı 2 atm, O₂\'ninki 2 atm\'dir. 2NO + O₂ → 2NO₂ tepkimesi sınırlayıcı bileşen bitene dek ilerlerse son toplam basınç kaç atm olur?', '3', ['4,5', '2', '1'], '2 atm NO, 1 atm O₂ ile birleşerek 2 atm NO₂ verir; 1 atm O₂ artar. Toplam 2 + 1 = 3 atm olur.'),
  ('Sabit hacimli bir kapta 1 atm CH₄ ile 3 atm O₂ karıştırılıp CH₄ + 2O₂ → CO₂ + 2H₂O tepkimesiyle CH₄ tamamen yakılıyor. Kap ilk sıcaklığa soğutulup su sıvılaştığında toplam basınç kaç atm olur? (Suyun buhar basıncını ihmal ediniz.)', '2', ['4,5', '3', '1'], '1 atm CH₄, 2 atm O₂ harcar ve 1 atm CO₂ verir; 1 atm O₂ artar. Su sıvı olduğundan toplam basınç 1 + 1 = 2 atm\'dir.'),
  ('Sabit hacim ve sıcaklıkta 2 atm SO₂ ile 1 atm O₂ içeren bir kapta 2SO₂ + O₂ → 2SO₃ tepkimesi bir süre ilerledikten sonra toplam basınç 2,5 atm\'ye iniyor. Bu anda SO₃\'ün kısmi basıncı kaç atm\'dir?', '1', ['0,5', '2', '1,5'], 'O₂\'den x atm harcanırsa toplam basınç 3 − x olur; 3 − x = 2,5\'ten x = 0,5 atm ve SO₃ = 2x = 1 atm bulunur.'),
  ('Hava yastıklarında 2NaN₃ → 2Na + 3N₂ tepkimesi kullanılır. 65 g NaN₃ tamamen ayrışırsa oluşan N₂ 27 °C ve 1,23 atm\'de kaç litre hacim kaplar? (NaN₃ = 65 g/mol, R = 0,082 L·atm/(mol·K))', '30', ['20', '36,9', '45'], '1 mol NaN₃\'ten 1,5 mol N₂ oluşur; V = 1,5 × 0,082 × 300 / 1,23 = 30 L.'),
  ('Hava yastığı karışımlarına sodyum azürün yanında potasyum nitrat ve silisyum dioksit gibi maddeler katılmasının amacı nedir?', 'Açığa çıkan aktif sodyumu zararsız hâle getirmek', ['Azot gazının sıcaklığını yükseltmek', 'Sodyum azürün kokusunu gidermek', 'Hava yastığının kumaşını yanmaz ve su geçirmez yapmak'], 'Ayrışmada açığa çıkan metalik sodyum çok aktiftir; KNO₃ ve SiO₂ ile tepkimeye girerek kararlı silikat camına dönüştürülür.'),
  ('2KClO₃ → 2KCl + 3O₂ tepkimesiyle 27 °C ve 1 atm\'de 7,38 L O₂ elde etmek için kaç gram KClO₃ ayrıştırılmalıdır? (KClO₃ = 122,5 g/mol, R = 0,082 L·atm/(mol·K))', '24,5', ['36,75', '12,25', '49,0'], 'n(O₂) = 7,38/24,6 = 0,3 mol; gereken KClO₃ = 0,3 × 2/3 = 0,2 mol, kütlesi 0,2 × 122,5 = 24,5 g.'),
  ('Rijit bir kapta 27 °C\'de 2 atm basınçta N₂O₄ bulunuyor. Kap 327 °C\'ye ısıtıldığında N₂O₄\'ün tamamı N₂O₄ → 2NO₂ tepkimesiyle ayrışıyor. Son basınç kaç atm olur?', '8', ['4', '6', '16'], 'Mol sayısı 2 katına, mutlak sıcaklık 300 K\'den 600 K\'ye 2 katına çıkar; basınç 2 × 2 × 2 = 8 atm olur.'),
  ('Eşit mol sayısında H₂ ve O₂ içeren bir karışım ince bir delikten vakuma sızmaya başlıyor. İlk anlarda delikten geçen gazda H₂ moleküllerinin O₂ moleküllerine oranı yaklaşık kaçtır?', '4', ['16', '1', '2'], 'Efüzyon hızları oranı √(32/2) = 4 olduğundan ilk sızan gazda her O₂ molekülüne karşı yaklaşık 4 H₂ molekülü bulunur.'),
  ('Uranyum zenginleştirmede ²³⁵UF₆ (349 g/mol) ile ²³⁸UF₆ (352 g/mol) moleküllerinin efüzyon hızları oranı yaklaşık kaçtır?', '1,0043', ['1,0086', '1,01282', '0,9957'], 'Hız oranı √(352/349) ≈ 1,0043\'tür; fark çok küçük olduğundan işlemin binlerce kez tekrarlanması gerekir.'),
  ('Efüzyonu difüzyondan ayıran temel koşul hangisidir?', 'Taneciklerin çok küçük bir delikten tek tek boşluğa çıkması', ['Gazın başka bir gazın içinde yavaş yavaş dağılması', 'Gazın yalnız yüksek sıcaklıklarda ve basınçlarda hareket etmesi', 'Gazın bir sıvı içinde çözünerek ilerlemesi'], 'Efüzyonda delik, ortalama serbest yoldan küçüktür; tanecikler delikten birbirleriyle çarpışmadan tek tek geçer. Difüzyon ise bir gazın başka bir ortamda karışarak yayılmasıdır.'),
  ('Çok yüksek basınçlarda (yüzlerce atm) bütün gazların sıkıştırılabilirlik faktörünün 1\'den büyük olmasının nedeni nedir?', 'Taneciklerin öz hacminin önem kazanması', ['Tanecikler arası çekimlerin tamamen yok olması', 'Sıcaklığın sıkıştırma sırasında kendiliğinden yükselmesi', 'Gaz moleküllerinin parçalanması'], 'Tanecikler birbirine çok yaklaştığında itme ve öz hacim etkisi baskınlaşır; gaz, idealin öngördüğünden daha zor sıkışır.'),
  ('Gerçek bir gazın düşük basınçlarda geniş bir aralıkta ideal gaz gibi davrandığı, yani çekim ve itme etkilerinin birbirini dengelediği sıcaklığa ne ad verilir?', 'Boyle sıcaklığı', ['Kritik sıcaklık', 'Üçlü nokta sıcaklığı', 'Ters dönme sıcaklığı'], 'Boyle sıcaklığında Z, düşük basınçlarda yaklaşık 1\'de kalır; bu sıcaklıkta gaz Boyle yasasına en iyi uyar.'),
  ('Van der Waals denklemindeki a sabitinin birimi, basınç atm ve hacim litre cinsinden alınırsa hangisidir?', 'L²·atm/mol²', ['L/mol', 'atm·L/(mol·K)', 'atm/mol²'], 'an²/V² terimi basınç birimi taşımalıdır; bu nedenle a\'nın birimi atm·L²/mol² olur.'),
  ('1 mol CO₂ 300 K\'de 1 L\'lik kapta bulunuyor. Van der Waals sabitleri a = 3,59 L²·atm/mol² ve b = 0,0427 L/mol ise gazın basıncı yaklaşık kaç atm\'dir? (R = 0,082 L·atm/(mol·K))', '22,1', ['24,6', '25,7', '28,25'], 'P = nRT/(V − nb) − an²/V² = 24,6/0,9573 − 3,59 ≈ 25,7 − 3,59 ≈ 22,1 atm. İdeal gaz 24,6 atm verirdi.'),
  ('Kritik sıcaklığı en düşük olduğu için en son sıvılaştırılan gaz helyumdur. Helyumu ilk kez 1908\'de sıvılaştıran bilim insanı kimdir?', 'Heike Kamerlingh Onnes', ['James Dewar', 'Carl von Linde', 'Louis Paul Cailletet'], 'Kamerlingh Onnes 1908\'de Leiden\'de helyumu sıvılaştırmış, bu sayede daha sonra süperiletkenliği de keşfetmiştir.'),
  ('Oda sıcaklığında bir gaz dar bir açıklıktan genleştirildiğinde soğumak yerine ısınıyor. Bu gaz aşağıdakilerden hangisi olabilir?', 'Hidrojen', ['Azot', 'Karbon dioksit', 'Oksijen'], 'Hidrojen ve helyumun Joule-Thomson ters dönme sıcaklıkları oda sıcaklığının altındadır; bu yüzden oda sıcaklığında genleşince ısınırlar.'),
  ('Pistonlu kapalı bir kapta 25 °C\'de bir miktar sıvı su ile hava bulunuyor; toplam basınç 760 mmHg, suyun buhar basıncı 24 mmHg\'dir. Sıcaklık sabitken hacim yarıya indirilir ve kapta yine sıvı su kalırsa toplam basınç kaç mmHg olur?', '1496', ['1520,5', '784', '1472'], 'Havanın kısmi basıncı 736 mmHg\'den 1472 mmHg\'ye çıkar; su buharının basıncı sıvıyla denge sürdüğü için 24 mmHg kalır: 1472 + 24 = 1496 mmHg.'),
  ('Kapalı bir kaptaki az miktardaki su tamamen buharlaşmış ve buharın kısmi basıncı o sıcaklıktaki doygun buhar basıncının altında kalmıştır. Bu durumda kabın hacmi sabit sıcaklıkta biraz artırılırsa su buharının kısmi basıncı nasıl değişir?', 'Boyle yasasına uygun olarak azalır', ['Doygun buhar basıncında sabit kalır', 'Artar, çünkü yeni su buharlaşır', 'Önce azalır sonra eski değerine döner'], 'Sıvı kalmadığında buhar sıradan bir gaz gibi davranır; hacim artınca kısmi basıncı da düşer. Sabit kalma ancak sıvıyla denge varken geçerlidir.'),
  ('Havadaki su buharının kısmi basıncı 12,8 mmHg\'dir. Suyun doygun buhar basıncı 10 °C\'de 9,2 mmHg, 15 °C\'de 12,8 mmHg ve 20 °C\'de 17,5 mmHg ise bu hava soğutulduğunda çiy oluşmaya hangi sıcaklıkta başlar?', '15 °C', ['10 °C', '20 °C', '0 °C'], 'Su buharı, kısmi basıncı doygun buhar basıncına eşit olduğu sıcaklıkta yoğuşmaya başlar; 12,8 mmHg değeri 15 °C\'ye karşılık gelir.'),
  ('Dünya atmosferinde basınç yükseklikle yaklaşık üstel olarak azalır. Deniz seviyesindeki basıncın kabaca yarıya indiği yükseklik yaklaşık kaç kilometredir?', '5,5', ['1,55', '15', '55'], 'Atmosfer basıncı yaklaşık her 5,5 km\'de yarıya iner; bu yüzden 5,5 km\'de yaklaşık 0,5 atm, 11 km\'de yaklaşık 0,25 atm ölçülür.'),
  ('Venüs\'ün yüzeyindeki atmosfer basıncı yaklaşık kaç atm\'dir?', '92', ['0,006', '1', '9,2'], 'Kalın ve büyük ölçüde CO₂\'den oluşan Venüs atmosferi yüzeyde yaklaşık 92 atm basınç oluşturur; bu, Dünya\'da yaklaşık 900 m deniz derinliğine denktir.'),
  ('Mars yüzeyindeki ortalama atmosfer basıncı Dünya\'nın deniz seviyesi basıncıyla karşılaştırıldığında hangisi doğrudur?', 'Yaklaşık %0,6\'sı kadardır', ['Yaklaşık iki katıdır', 'Yaklaşık yarısı kadardır', 'Dünya\'dakinin yaklaşık 92 katıdır'], 'Mars\'ta ortalama yüzey basıncı yaklaşık 0,006 atm\'dir (yaklaşık 600 Pa); bu nedenle sıvı su yüzeyde kararlı kalamaz.'),
  ('Bir dalgıcın tüpü 20 m derinlikte, yüzeyde dayanacağı sürenin yaklaşık üçte biri kadar dayanır. Bunun nedeni nedir?', 'Her nefesin üç kat fazla hava molekülü içermesi', ['Derinde suyun soğuk olması nedeniyle daha hızlı solunması', 'Tüpteki havanın derinde kimyasal olarak bozunması', 'Derinde tüp vanasından gaz sızması'], 'Regülatör havayı çevre basıncında verir; 20 m\'de basınç 3 atm olduğundan aynı akciğer hacmini doldurmak için 3 kat fazla hava harcanır.'),
  ('Düşey bir silindirde gaz, kütlesi 10 kg ve kesit alanı 0,01 m² olan sürtünmesiz bir pistonla kapatılmıştır. Açık hava basıncı 101 kPa ve g = 10 m/s² ise gazın basıncı kaç kPa\'dır?', '111', ['101', '91', '1101'], 'Pistonun ağırlığı 100 N olup 0,01 m² alana 10 000 Pa = 10 kPa basınç yapar; gaz basıncı 101 + 10 = 111 kPa olur.'),
  ('Toplam hacmi 30 L olan yalıtılmış bir silindir serbest bir pistonla iki eşit bölüme ayrılmış, her bölümde 300 K\'de eşit mol sayısında gaz bulunuyor. Sol bölüm 600 K\'ye ısıtılıp sağ bölüm 300 K\'de tutulursa sol bölümün hacmi kaç L olur?', '20', ['15', '10', '22,5'], 'Basınçlar eşit kalacağından hacimler nT çarpımıyla orantılıdır: 600 : 300 = 2 : 1; sol bölüm 30 × 2/3 = 20 L olur.'),
  ('John Dalton kısmi basınçlar yasasını hangi yıl ortaya koymuştur?', '1801', ['1662,5', '1834', '1869'], 'Dalton, gaz karışımlarında her gazın tek başına davranıyormuş gibi basınç yaptığını 1801\'de ileri sürmüştür.'),
  ('Gay-Lussac 1804\'te bir balonla yaklaşık 7000 m yüksekliğe çıkarak hangi sonuca ulaşmıştır?', 'Yükseklerdeki havanın bileşiminin yerdekiyle aynı olduğuna', ['Yükseklerde oksijenin tamamen bittiğine', 'Yükseklerde havanın sıcaklıkla genleşmediğine', 'Yükseklerde havanın büyük kısmının hidrojen olduğuna'], 'Gay-Lussac yüksekte aldığı hava örneklerini inceleyerek havanın bileşiminin yükseklikle belirgin biçimde değişmediğini göstermiştir.'),
  ('Boyle, Charles ve Avogadro yasalarını birleştirerek ideal gaz denklemini 1834\'te ilk kez ifade eden Fransız mühendis kimdir?', 'Émile Clapeyron', ['Sadi Carnot', 'Joseph Fourier', 'Henri Becquerel'], 'Émile Clapeyron 1834\'te bu yasaları tek bir bağıntıda toplamıştır; denklem bu yüzden Clapeyron denklemi olarak da anılır.'),
  ('1869\'da karbon dioksit üzerinde yaptığı deneylerle kritik nokta kavramını ortaya koyan İrlandalı kimyacı kimdir?', 'Thomas Andrews', ['Thomas Graham', 'William Henry', 'Humphry Davy'], 'Andrews, CO₂\'nin yaklaşık 31 °C\'nin üzerinde hangi basınç uygulanırsa uygulansın sıvılaşmadığını göstererek kritik sıcaklığı tanımlamıştır.'),
  ('Lord Rayleigh havadan elde edilen azotun, amonyağın ayrıştırılmasıyla elde edilen azottan biraz daha yoğun olduğunu buldu. Bu fark hangi keşfe yol açmıştır?', 'Argonun keşfine', ['Ozonun keşfine', 'Döteryumun keşfine', 'Azotun iki atomlu olduğunun bulunmasına'], 'Havadan elde edilen \'azot\' içinde daha ağır bir gaz bulunduğu anlaşılmış; Rayleigh ve Ramsay 1894\'te bu gazı argon olarak tanımlamıştır.'),
  ('Gaz moleküllerinin çarpışmalar arasında aldığı \'ortalama serbest yol\' kavramını 1858\'de ortaya atan Alman fizikçi kimdir?', 'Rudolf Clausius', ['Ludwig Boltzmann', 'Max Planck', 'Hermann von Helmholtz'], 'Clausius, gaz moleküllerinin çok hızlı olmasına karşın difüzyonun yavaşlığını açıklamak için ortalama serbest yol kavramını önermiştir.'),
  ('Kinetik teoriye göre aynı sıcaklık ve basınçta eşit hacimdeki gazların eşit sayıda tanecik içermesi (Avogadro yasası) nasıl açıklanır?', 'Aynı sıcaklıkta ortalama kinetik enerjilerin eşit olması', ['Bütün gaz taneciklerinin kütlelerinin birbirine eşit olması', 'Bütün gaz taneciklerinin çaplarının eşit olması', 'Taneciklerin birbirini aynı kuvvetle çekmesi'], 'Basınç, birim hacimdeki tanecik sayısı ile ortalama kinetik enerjinin çarpımıyla orantılıdır; enerji eşitse eşit basınç eşit tanecik yoğunluğu gerektirir.'),
  ('Kapalı bir kaptaki gaz molekülleri, kap hızla giden bir trenin içindeyken de aynı sıcaklıktadır. Bu durumu en iyi açıklayan ifade hangisidir?', 'Sıcaklık, taneciklerin rastgele hareketine bağlıdır', ['Trenin hızı moleküllerin hızına eklenip sıcaklığı artırır', 'Moleküller trenle birlikte hareket edemediği için soğur', 'Sıcaklık yalnız gazın basıncına bağlı olduğundan değişmez'], 'Sıcaklık, taneciklerin birbirine göre rastgele hareketinin ortalama enerjisini ölçer; bütün kabın düzgün hareketi bu rastgele hareketi değiştirmez.'),
  ('Bir gazın bütün moleküllerinin hızı iki katına çıkarılır ve birim hacimdeki molekül sayısı sabit tutulursa basınç kaç katına çıkar?', '4', ['2', '8', '√2'], 'Kinetik teoriye göre basınç birim hacimdeki tanecik sayısı ve v² ile orantılıdır; hız iki katına çıkınca basınç 4 katına çıkar.'),
  ('Bir ultra yüksek vakum odasında 300 K\'de basınç 10⁻⁹ atm\'ye indirilmiştir. Odanın her cm³\'ünde yaklaşık kaç gaz molekülü kalır? (R = 0,082 L·atm/(mol·K), Nₐ = 6,02·10²³)', '2,4·10¹⁰', ['0', '4,1·10⁻¹¹', '2,7·10¹⁹'], 'n/V = P/RT = 10⁻⁹/24,6 ≈ 4,1·10⁻¹¹ mol/L; bu 2,4·10¹³ molekül/L, yani 2,4·10¹⁰ molekül/cm³ eder. \'Boşluk\' bile milyarlarca molekül içerir.'),
  ('5 m × 4 m × 3 m boyutlarındaki bir odadaki havanın kütlesi 27 °C ve 1 atm\'de yaklaşık kaç kilogramdır? (Hava = 29 g/mol, R = 0,082 L·atm/(mol·K))', '71', ['7,1', '29', '710'], 'V = 60 m³ = 60 000 L; n = 60 000/24,6 ≈ 2439 mol; kütle ≈ 2439 × 29 g ≈ 70,7 kg.'),
  ('Rijit bir tank 300 K\'de belirli bir basınçta gazla doludur. Tank 375 K\'ye ısıtılırken basıncın değişmemesi için içindeki gazın yüzde kaçı dışarı bırakılmalıdır?', '20', ['25,5', '80', '75'], 'Sabit P ve V\'de nT çarpımı sabit kalmalıdır: n₂ = n₁ × 300/375 = 0,8 n₁; gazın %20\'si bırakılmalıdır.'),
  ('27 °C\'de 10 atm basınç gösteren rijit bir gaz tüpü bir süre sonra 7 °C\'de 7 atm gösteriyor. Bu sürede tüpteki gazın yüzde kaçı sızmıştır?', '25', ['30', '70', '7,5'], 'n ∝ P/T\'dir: başlangıçta 10/300, sonra 7/280. Oran (7/280)/(10/300) = 0,75 olduğundan gazın %25\'i sızmıştır.'),
  ('Bir He-O₂ karışımında He\'nin kısmi basıncı O₂\'ninkinin iki katıdır. Karışımda He\'nin kütlece yüzdesi kaçtır? (He = 4, O₂ = 32 g/mol)', '20', ['67,5', '33', '11'], 'Mol oranı He : O₂ = 2 : 1\'dir; kütleler 2 × 4 = 8 g ve 32 g olduğundan He\'nin kütle yüzdesi 8/40 = %20\'dir.'),
  ('Normal koşullarda 1 m³ helyumun havada sağlayabileceği net kaldırma kabaca kaç kilogramlık yüke karşılık gelir? (Hava = 29, He = 4 g/mol)', '1,1', ['0,18', '1,3', '4,0'], '1 m³ hava 29/22,4 ≈ 1,29 kg, 1 m³ He 4/22,4 ≈ 0,18 kg\'dır; fark yaklaşık 1,1 kg\'lık kaldırmayı verir.'),
  ('Hidrojenin mol kütlesi helyumun yarısı kadar olduğu hâlde, aynı hacimdeki hidrojen balonunun kaldırma gücü helyumunkinden yalnız yaklaşık %8 fazladır. Bunun nedeni nedir?', 'Kaldırmayı havayla gaz arasındaki yoğunluk farkı belirler', ['Hidrojen balonu helyum balonundan daha çabuk sızdırdığı için', 'Hidrojenin yoğunluğu aslında helyumdan büyük olduğu için', 'Kaldırma yalnız balon zarının ağırlığına bağlı olduğu için'], 'Kaldırma, (29 − M) ile orantılıdır: hidrojen için 27, helyum için 25 birimdir; oran yalnız yaklaşık 1,08\'dir.'),
  ('10 mL CO ve CO₂ karışımı fazla oksijenle karıştırılıp yakılıyor. Aynı koşullarda ölçülen toplam gaz hacmi tepkimeden sonra 2 mL azalıyor. İlk karışımda kaç mL CO₂ vardı?', '6', ['4,5', '2', '8'], '2CO + O₂ → 2CO₂ tepkimesinde her 2 mL CO için hacim 1 mL azalır; 2 mL azalma 4 mL CO\'ya karşılık gelir, CO₂ = 10 − 4 = 6 mL\'dir.'),
  ('Aynı basınçta tutulan iki farklı gaz örneği için V-T(K) grafiğinde birinci örneğin doğrusu ikincisininkinden daha diktir. Bu durum neyi gösterir?', 'Birinci örnekte daha fazla mol gaz bulunduğunu', ['Birinci gazın mol kütlesinin daha büyük olduğunu', 'Birinci gazın daha düşük sıcaklıkta olduğunu', 'İkinci gazın ideal davranmadığını'], 'Eğim nR/P\'dir; basınçlar eşitse eğimi büyük olan doğru, mol sayısı büyük olan örneğe aittir. Gazın türü eğimi etkilemez.'),
  ('Ağzı açık bir balon joje 1 atm\'de ısıtılıyor; gaz dışarı çıkabildiği için basınç ve hacim sabit kalıyor. Balondaki gazın mol sayısının mutlak sıcaklığa karşı grafiği nasıldır?', 'n·T çarpımı sabit kalan, azalan bir eğri', ['Başlangıçtan geçen artan bir doğru', 'Sıcaklık eksenine paralel bir doğru', 'Sıcaklıkla üstel olarak artan bir eğri'], 'PV = nRT\'de P ve V sabitse n·T = PV/R sabittir; sıcaklık arttıkça balondaki mol sayısı ters orantılı olarak azalır.'),
  ('Oda sıcaklığında farklı gazların sıkıştırılabilirlik faktörünün (Z) basınçla değişimi inceleniyor. Hidrojen için hangisi gözlenir?', 'Basınç arttıkça Z sürekli olarak 1\'in üstünde artar', ['Z önce 1\'in altına düşer, sonra yükselir', 'Z her basınçta tam olarak 1\'dir', 'Z basınç arttıkça sıfıra yaklaşır'], 'Hidrojenin moleküller arası çekimleri çok zayıftır; oda sıcaklığında öz hacim etkisi baskın olduğundan Z basınçla birlikte 1\'in üzerinde artar.'),
  ('Metan için oda sıcaklığında sıkıştırılabilirlik faktörü basınçla nasıl değişir?', 'Önce 1\'in altına düşer, yüksek basınçlarda 1\'in üstüne çıkar', ['Basınç arttıkça sürekli 1\'in üstünde artar', 'Her basınçta 1\'e eşit kalır', 'Basınç arttıkça sürekli azalarak sonunda sıfıra yaklaşır ve orada kalır'], 'Orta basınçlarda çekimler baskın olduğundan Z < 1\'dir; çok yüksek basınçta öz hacim etkisi ağır basar ve Z > 1 olur.'),
  ('Bir gazın Z değeri tam olarak 1 ölçülmüştür. Bu ölçümden çıkarılabilecek en doğru sonuç hangisidir?', 'Bu koşulda gaz ideal gaz denklemine uymaktadır', ['Gazın molekülleri arasında hiçbir çekim kuvveti bulunmamaktadır', 'Gazın molekülleri hiç hacim kaplamaz', 'Gaz her koşulda ideal davranır'], 'Z = 1 olması, o koşulda çekim ve öz hacim etkilerinin birbirini dengelediğini gösterir; etkilerin yok olduğu anlamına gelmez.'),
  ('Van der Waals \'a\' sabitleri karşılaştırıldığında hangi sıralama doğrudur?', 'He < N₂ < CO₂ < H₂O', ['H₂O < CO₂ < N₂ < He', 'N₂ < He < H₂O < CO₂', 'CO₂ < H₂O < He < N₂'], 'a sabiti moleküller arası çekimin ölçüsüdür; soy gaz helyumda en küçük, hidrojen bağı yapan suda en büyüktür.'),
  ('Karbon monoksit zehirlenmesinde hastanın basınçlı odada (hiperbarik oda) saf oksijen soluması tedaviyi neden hızlandırır?', 'Oksijenin kısmi basıncı arttıkça kana geçen oksijen artar', ['Basınçlı odada karbon monoksit sıvılaşıp akciğerde kalır', 'Yüksek basınç hemoglobini parçalayıp yeniler', 'Basınç arttıkça kanın sıcaklığı düşer ve CO donar'], 'Toplam basınç ve oksijen oranı yükseldiğinden O₂\'nin kısmi basıncı birkaç atm\'ye çıkar; bu, CO\'nun hemoglobinden uzaklaştırılmasını ve dokulara oksijen taşınmasını hızlandırır.'),
  ('2019\'da SI birimlerinin yeniden tanımlanmasıyla kelvin hangi temel sabitin değeri tam olarak sabitlenerek tanımlanmaya başlamıştır?', 'Boltzmann sabiti', ['Avogadro sabiti', 'Planck sabiti', 'Işık hızı'], 'Kelvin artık suyun üçlü noktasıyla değil, Boltzmann sabitinin k = 1,380649·10⁻²³ J/K olarak sabitlenmesiyle tanımlanır.'),
  ('Şnorkelle yüzerken borunun yalnız 30-40 cm kadar uzun yapılmasının nedeni nedir?', 'Derinde göğüs su basıncına karşı genişleyemez', ['Uzun boruda hava sıvılaşır', 'Uzun borudaki havanın oksijeni tükenir', 'Uzun borudan geçen hava ısınarak akciğerlere zarar verir'], 'Boru yüzeydeki 1 atm\'lik havayı getirir; göğüs ise derinlikle artan su basıncı altındadır. Bu fark büyüdükçe solunum kasları göğsü genişletemez.'),
  ('Normal koşullardaki bir gazda moleküllerin kendi öz hacimlerinin toplamı, gazın kapladığı hacmin yaklaşık ne kadarıdır?', 'Binde biri düzeyinde', ['Yarısı kadar', 'Onda biri kadar', 'Tamamı kadar'], 'Normal koşullarda moleküllerin öz hacmi toplam hacmin yaklaşık %0,1\'i kadardır; gaz hacminin büyük bölümü boşluktur.'),
  ('Bir gaz molekülünün ortalama hızı v̄ = √(8RT/πM) ile verilir. Aynı gaz için en olası hız hangi bağıntıyla hesaplanır?', '√(2RT/M)', ['√(3RT/M)', '√(RT/2M)', '√(8RT/M)'], 'Maxwell-Boltzmann dağılımının tepe noktası en olası hızdır ve √(2RT/M) ile verilir; bu üç hızın en küçüğüdür.'),
  ('Bir gazın kök ortalama kare hızının en olası hızına oranı kaçtır?', '√(3/2) ≈ 1,22', ['√2 ≈ 1,41', '3/2 = 1,50', '√(8/π) ≈ 1,60'], 'vₖₒₖ/vₒ = √(3RT/M) / √(2RT/M) = √(3/2) ≈ 1,22; oran gazın türünden ve sıcaklıktan bağımsızdır.'),
  ('İdeal bir gaz yalıtılmış bir kaptan, ara bölme kaldırılarak boş bir bölmeye serbestçe genleştiriliyor. Joule\'ün deneyine göre gazın sıcaklığı nasıl değişir?', 'Değişmez', ['Belirgin biçimde artar', 'Belirgin biçimde azalır', 'Mutlak sıfıra iner'], 'İdeal gazda tanecikler arası etkileşim olmadığından boşluğa genleşmede iş yapılmaz ve iç enerji değişmez; sıcaklık sabit kalır.'),
  ('10 L\'lik bir tüpte 150 atm basınçta helyum vardır. Tüp en fazla 1 atm basınca kadar boşaltılabiliyorsa bu helyumla 1 atm\'de 2 L hacimli kaç balon şişirilebilir? (Sıcaklık sabit)', '745', ['750', '1490', '300'], 'Kullanılabilen gaz (150 − 1) × 10 = 1490 L·atm\'dir; 1 atm\'de 1490 L hacim, 2 L\'lik 745 balonu doldurur.'),
  ('LPG yalnız basınç uygulanarak sıvılaştırılabilirken doğal gazın sıvılaştırılması (LNG) için yaklaşık −162 °C\'ye kadar soğutma gerekir. Bu farkın nedeni nedir?', 'Metanın kritik sıcaklığının çok düşük olması', ['Metanın mol kütlesinin propan ve bütandan büyük olması', 'Doğal gazın içinde su buharı bulunması', 'Metanın yüksek basınçta kendiliğinden yanması'], 'Metanın kritik sıcaklığı yaklaşık −82 °C\'dir; bu sıcaklığın üstünde ne kadar basınç uygulansa da sıvılaşmaz, bu yüzden önce soğutulması gerekir.'),
  ('Van der Waals denklemindeki b sabiti, bir mol molekülün gerçek öz hacmiyle karşılaştırıldığında yaklaşık nasıldır?', 'Öz hacmin yaklaşık dört katıdır', ['Öz hacmin yarısı kadardır', 'Öz hacme tam olarak eşittir', 'Öz hacmin yaklaşık yüz katıdır'], 'Küresel moleküller birbirine en fazla merkezleri arasında bir çap kadar yaklaşabildiğinden dışlanan hacim, moleküllerin öz hacminin yaklaşık dört katı çıkar.'),
  ('Van der Waals denkleminden türetilen kritik sıcaklık bağıntısı hangisidir?', 'T꜀ = 8a / (27Rb)', ['T꜀ = a / (Rb)', 'T꜀ = 27a / (8Rb)', 'T꜀ = 8b / (27Ra)'], 'Van der Waals izoterminin büküm noktası koşullarından T꜀ = 8a/(27Rb), P꜀ = a/(27b²) ve V꜀ = 3b bulunur.'),
  ('Farklı gazlar kritik sıcaklık ve kritik basınçlarına göre aynı oranda (aynı indirgenmiş koşullarda) bulunduklarında sıkıştırılabilirlik faktörlerinin birbirine yakın olduğunu söyleyen ilkeye ne ad verilir?', 'Karşılık gelen hâller ilkesi', ['Kısmi basınçlar yasası', 'Birleşen hacimler yasası', 'Eş bölüşüm ilkesi'], 'Van der Waals\'ın önerdiği bu ilkeye göre gerçek gazlar indirgenmiş sıcaklık ve basınçla ifade edildiğinde benzer davranış gösterir.'),
  ('Gerçek gaz davranışını Z = 1 + B/Vₘ + C/Vₘ² + ... biçiminde bir seriyle ifade eden denkleme ne ad verilir?', 'Virial denklemi', ['Clapeyron denklemi', 'Graham denklemi', 'Arrhenius denklemi'], 'Virial denkleminde B, C gibi katsayılar sıcaklığa bağlıdır ve ideallikten sapmayı ölçer; B\'nin sıfır olduğu sıcaklık Boyle sıcaklığıdır.'),
  ('Joule-Thomson ters dönme sıcaklığı için hangisi doğrudur?', 'Bu sıcaklığın altında genleşen gaz soğur, üstünde ısınır', ['Bu sıcaklığın altında gaz sıvılaşamaz', 'Bu sıcaklıkta gazın basıncı sıfır olur', 'Bu sıcaklık bütün gazlar için aynı olup gazın türüne bağlı değildir'], 'Ters dönme sıcaklığı Joule-Thomson katsayısının işaret değiştirdiği sıcaklıktır; azotunki oda sıcaklığının çok üstünde, hidrojeninki ise altındadır.'),
  ('İçinde hava bulunan gözenekli bir toprak kap bir manometreye bağlanıp üzerine hidrojen dolu bir beher kapatılıyor. İlk anlarda manometre kaptaki basınç için ne gösterir?', 'Kap içindeki basınç geçici olarak artar', ['Kap içindeki basınç geçici olarak azalır', 'Basınç hiç değişmez', 'Basınç önce sıfıra iner sonra eski değerine döner'], 'Hafif H₂ molekülleri gözeneklerden içeri, ağır hava moleküllerinin dışarı çıktığından daha hızlı girer; kapta geçici olarak gaz birikir ve basınç yükselir.'),
  ('Aynı sıcaklıkta aynı gaz, aynı küçük delikten vakuma efüzyon yapıyor. Kaptaki gaz basıncı iki katına çıkarılırsa birim zamanda delikten kaçan molekül sayısı nasıl değişir?', 'İki katına çıkar', ['Değişmez', '√2 katına çıkar', 'Yarıya iner'], 'Efüzyon hızı deliğe birim zamanda çarpan molekül sayısıyla, bu da birim hacimdeki molekül sayısıyla, yani basınçla orantılıdır.'),
  ('2,46 L\'lik kapalı bir balonda 27 °C\'de bir tepkime gaz üretiyor. Balona bağlı ucu açık manometrede cıva seviyeleri başlangıçta eşitken sonunda gaz tarafındaki kol 38 cm aşağıda kalıyor. Sıcaklık sabitse kaç mol gaz oluşmuştur? (R = 0,082 L·atm/(mol·K))', '0,05', ['0,5', '0,15', '0,005'], 'Basınç artışı 38 cmHg = 0,5 atm\'dir; oluşan gaz n = ΔP·V/RT = 0,5 × 2,46/24,6 = 0,05 mol.'),
  ('Sabit basınçta 1 mol gazın sıcaklığı 1 K artırıldığında hacmindeki artış (ideal gaz için) hangi ifadeyle verilir?', 'R/P', ['RT/P', 'P/R', 'nRT'], 'V = nRT/P bağıntısında n = 1 için T 1 K artınca hacim R/P kadar artar; örneğin 1 atm\'de yaklaşık 0,082 L.'),
  ('Kapalı bir kapta hem hava hem de bir miktar sıvı aseton bulunuyor. Kap 20 °C\'den 30 °C\'ye ısıtılınca toplam basınçtaki artış için hangisi doğrudur?', 'Havanın basıncı az, aseton buharınınki daha fazla oranda artar', ['Yalnız havanın basıncı artar, buharınki sabittir', 'Yalnız buharın basıncı artar, havanınki sabittir', 'İki basınç da aynı oranda, yani tam 303/293 katı kadar artar'], 'Hava Gay-Lussac yasasına göre yalnız yaklaşık %3,4 artar; sıvıyla dengedeki buharın basıncı ise sıcaklıkla çok daha hızlı yükselir.'),
  ('25 °C ve 1 bar koşullarında (IUPAC\'ın standart ortam koşulları) 1 mol ideal gazın hacmi yaklaşık kaç litredir?', '24,8', ['22,45', '22,7', '24,5'], 'V = RT/P = 0,08314 L·bar/(mol·K) × 298,15 K / 1 bar ≈ 24,8 L bulunur.'),
  ('25 °C\'de boşaltılmış 10 L\'lik bir kaba 0,01 mol su enjekte ediliyor. 25 °C\'de suyun buhar basıncı 23,8 mmHg ise kapta denge kurulduğunda ne gözlenir? (R = 0,082 L·atm/(mol·K))', 'Suyun tamamı buharlaşır ve basınç yaklaşık 18,6 mmHg olur', ['Bir miktar sıvı kalır ve basınç 23,8 mmHg olur', 'Suyun tamamı buharlaşır ve basınç 23,8 mmHg olur', 'Su hiç buharlaşmaz ve basınç sıfır kalır'], 'Suyun tamamı buharlaşsaydı P = 0,01 × 0,082 × 298/10 ≈ 0,0244 atm ≈ 18,6 mmHg olurdu; bu değer buhar basıncından küçük olduğundan su tamamen buharlaşır.'),
  ('Bazı dalgıçların normal hava yerine oksijen oranı %32 gibi daha yüksek olan \'nitroks\' karışımı solumasının amacı nedir?', 'Azotun kısmi basıncını düşürüp kanda daha az azot çözünmesini sağlamak', ['Daha derine güvenle inmeyi sağlamak için oksijeni azaltmak', 'Karışımın yoğunluğunu artırıp batmayı kolaylaştırmak', 'Solunan gazın sıcaklığını yükseltmek'], 'Azot oranı azalınca aynı derinlikte azotun kısmi basıncı düşer; vurgun riski azalır. Ancak yüksek oksijen nedeniyle inilebilecek en büyük derinlik sınırlanır.'),
  ('Kinetik teoride m kütleli bir tanecik v hızıyla çepere dik çarpıp esnek olarak geri döndüğünde çepere aktardığı momentum ne kadardır?', '2mv', ['mv', 'mv/2', '0'], 'Hız v\'den −v\'ye döndüğünden taneciğin momentum değişimi 2mv\'dir; aynı büyüklükte itme çepere aktarılır ve basıncı oluşturur.'),
  ('Kinetik teoriye göre P = (1/3)ρ·vₖₒₖ² bağıntısı yazılabilir. Yoğunluğu 1,29 kg/m³ olan havanın 101 325 Pa basınçtaki kök ortalama kare hızı yaklaşık kaç m/s\'dir?', '485', ['280', '343', '1450'], 'vₖₒₖ = √(3P/ρ) = √(3 × 101 325 / 1,29) ≈ √235 640 ≈ 485 m/s bulunur.'),
  ('Karbon dioksit tüplerinde içerideki CO₂ oda sıcaklığında kısmen sıvı hâlde bulunur. Tüpte ne kadar CO₂ kaldığını anlamak için basınç göstergesi yerine tüpün tartılması neden tercih edilir?', 'Sıvı kaldıkça basınç buhar basıncında sabit kalır', ['CO₂\'nin basıncı sıcaklıktan bağımsız olduğu için', 'Göstergeler CO₂ ile tepkimeye girdiği için', 'Tüpteki CO₂\'nin kütlesi zamanla kendiliğinden arttığı için'], 'Tüpte sıvı CO₂ bulundukça buhar sıvıyla dengededir ve basınç o sıcaklıktaki buhar basıncına eşit kalır; basınç ancak sıvı tükenince düşmeye başlar.'),
  ('Gazları su dolu ters çevrilmiş kaplarda toplamaya yarayan \'pnömatik tekne\' düzeneğini 1720\'lerde geliştiren İngiliz bilim insanı kimdir?', 'Stephen Hales', ['Joseph Black', 'Henry Cavendish', 'John Mayow'], 'Stephen Hales, ürettiği gazları ısıtma kabından ayrı bir su teknesinde toplayarak pnömatik kimyanın gelişmesine önemli katkı yapmıştır.'),
  ('Eşit hacimli iki cam balon ince bir boruyla birbirine bağlıdır ve içlerinde toplam 3 mol ideal gaz vardır. Balonlardan biri 300 K\'de, diğeri 600 K\'de tutulursa 300 K\'deki balonda kaç mol gaz bulunur?', '2', ['1', '1,5', '2,5'], 'Bağlı balonlarda basınç eşittir; V de eşit olduğundan n·T çarpımı eşit olmalıdır: n₁ × 300 = n₂ × 600, n₁ = 2n₂ ve n₁ + n₂ = 3\'ten n₁ = 2 mol.'),
  ('Farklı gazlarla doldurulmuş sabit hacimli gaz termometreleri yüksek basınçta biraz farklı sıcaklıklar gösterir, ancak gaz basıncı azaltıldıkça okumalar birbirine yaklaşır. Bunun nedeni nedir?', 'Düşük basınçta bütün gazların ideal davranışa yaklaşması', ['Düşük basınçta gazların mol kütlelerinin eşitlenmesi', 'Düşük basınçta termometre camının daha az genleşmesi', 'Düşük basınçta bütün gazların aynı kimyasal türe dönüşmesi'], 'Basınç sıfıra yaklaştıkça moleküller arası etkileşimler önemsizleşir ve P ∝ T ilişkisi gazın türünden bağımsız hâle gelir; ideal gaz sıcaklık ölçeği buna dayanır.'),
  ('Bir öğrenci uçucu bir sıvının buharının mol kütlesini ideal gaz denklemiyle bulmak istiyor. Ölçümün yüksek basınç yerine düşük basınçta ve kaynama noktasının epey üzerinde yapılması neden önerilir?', 'Bu koşullarda buhar ideal gaz gibi davrandığı için', ['Bu koşullarda buharın mol kütlesi gerçekten küçüldüğü için', 'Yüksek basınçta ideal gaz sabiti R\'nin değeri değiştiği için', 'Düşük basınçta buhar kimyasal olarak bozunmadığı için'], 'Kaynama noktasına yakın ve yüksek basınçta moleküller arası çekimler belirgindir; ideal gaz denklemi sapmalı sonuç verir. Düşük basınç ve yüksek sıcaklık sapmayı azaltır.'),
  ('10 g kireç taşı örneği yeterli HCl ile tepkimeye girdiğinde 27 °C ve 1 atm\'de 1,968 L CO₂ açığa çıkıyor. Örnekteki CaCO₃\'ün kütlece yüzdesi kaçtır? (CaCO₃ = 100 g/mol, R = 0,082 L·atm/(mol·K))', '80', ['88,5', '20', '98'], 'n(CO₂) = 1,968/24,6 = 0,08 mol = n(CaCO₃); kütle 8 g olduğundan saflık %80\'dir.'),
  ('Sabit hacimde tek atomlu ideal bir gazın molar ısı sığası (3/2)R\'dir. Bu değer yaklaşık kaç J/(mol·K)\'dir? (R = 8,314 J/(mol·K))', '12,5', ['8,3', '20,85', '24,9'], '(3/2) × 8,314 ≈ 12,5 J/(mol·K); verilen ısının tamamı öteleme kinetik enerjisini artırır.'),
  ('Aynı sıcaklıkta iki atomlu bir gazın (örneğin N₂) bir molünün iç enerjisinin tek atomlu bir gazınkinden (örneğin Ar) büyük olmasının nedeni nedir?', 'Moleküllerin öteleme yanında dönme hareketi de yapması', ['Moleküllerin daha hızlı öteleme hareketi yapması', 'Moleküllerin birbirini daha güçlü çekmesi', 'Moleküllerin daha küçük olması'], 'Ortalama öteleme enerjisi iki gazda eşittir; ancak iki atomlu moleküller dönme hareketiyle de enerji depolar.'),
  ('Sıvı helyumun 1 atm\'deki kaynama noktası yaklaşık kaç kelvindir?', '4,2', ['77', '20,3', '90,2'], 'Helyum 1 atm\'de yaklaşık 4,2 K\'de kaynar; 77 K azotun, 20,3 K hidrojenin, 90,2 K oksijenin kaynama noktasıdır.'),
  ('Normal koşullarda bir azot molekülünün saniyede yaptığı çarpışma sayısı hangi büyüklük mertebesindedir?', 'Milyarlarca (yaklaşık 10⁹)', ['Birkaç tane', 'Yüzlerce (yaklaşık 10²)', 'Binlerce (yaklaşık 10³)'], 'Yüzlerce m/s hızla giden ve ortalama serbest yolu yaklaşık 10⁻⁷ m olan bir molekül saniyede birkaç milyar kez çarpışır.'),
  ('Normal koşullarda hava moleküllerinin ortalama serbest yolu hangi büyüklük mertebesindedir?', 'Yaklaşık 10⁻⁷ m', ['Yaklaşık 1 m', 'Yaklaşık 1 mm', 'Yaklaşık 10⁻¹⁵ m'], 'Normal koşullarda ortalama serbest yol yaklaşık 70 nm (10⁻⁷ m düzeyi) olup molekül çapından birkaç yüz kat büyüktür.'),
  ('Sabit hacimli kapalı bir kaptaki gazın mutlak sıcaklığı iki katına çıkarılırsa birim zamanda çepere yapılan çarpma sayısı ile her çarpmanın ortalama itmesi nasıl değişir?', 'İkisi de √2 katına çıkar ve basınç 2 katına çıkar', ['Çarpma sayısı 2, itme 2 katına çıkar ve basınç 4 katına çıkar', 'Çarpma sayısı değişmez, itme 2 katına çıkar', 'Çarpma sayısı 2 katına çıkar, itme değişmez'], 'Hız √2 kat artar; hem çarpma sıklığı hem her çarpmanın momentum aktarımı hızla orantılıdır, çarpımları 2 eder ve Gay-Lussac yasasıyla uyumludur.'),
  ('2000 m³ hacimli bir sıcak hava balonunda zarf ve yükün toplam kütlesi 500 kg\'dır. Dış hava 27 °C\'de ve yoğunluğu 1,18 kg/m³ ise balonun yükselebilmesi için içerideki hava en az yaklaşık kaç °C\'ye ısıtılmalıdır? (Basınçlar eşit kabul edilecek)', '108', ['81', '27', '135,5'], 'Gereken iç yoğunluk 1,18 − 500/2000 = 0,93 kg/m³\'tür; d ∝ 1/T olduğundan T = 300 × 1,18/0,93 ≈ 381 K ≈ 108 °C bulunur.'),
  ('CH₄ ve N₂\'den oluşan bir karışımın 27 °C ve 1 atm\'deki yoğunluğu 1,0 g/L\'dir. Karışımdaki CH₄\'ün mol yüzdesi yaklaşık kaçtır? (CH₄ = 16, N₂ = 28 g/mol, R = 0,082 L·atm/(mol·K))', '28', ['72,5', '50', '40'], 'Ortalama mol kütlesi M = dRT/P = 1,0 × 24,6 = 24,6 g/mol; 16x + 28(1 − x) = 24,6 eşitliğinden x ≈ 0,28 bulunur.'),
  ('Aynı gaz, aynı sıcaklık ve basınçta biri diğerinin iki katı alana sahip iki küçük delikten ayrı ayrı vakuma efüzyon yapıyor. Büyük delikten birim zamanda kaçan molekül sayısı küçük olanınkinin kaç katıdır?', '2', ['√2', '4', '1'], 'Efüzyon hızı birim zamanda deliğe çarpan molekül sayısıyla, bu da deliğin alanıyla doğru orantılıdır.'),
  ('Everest Dağı\'nın zirvesindeki (yaklaşık 8850 m) atmosfer basıncı deniz seviyesindekinin yaklaşık ne kadarıdır?', 'Üçte biri', ['Onda biri', 'Yarısı', 'Dörtte üçü'], 'Everest zirvesinde basınç yaklaşık 0,33 atm (yaklaşık 250 mmHg) dolayındadır; oksijenin kısmi basıncı da aynı oranda düşüktür.'),
  ('Bir öğrenci \'Bu tek oksijen molekülünün sıcaklığı 300 K\'dir\' diyor. Bu ifade kinetik teori açısından neden sorunludur?', 'Sıcaklık çok sayıda taneciğin ortalama enerjisini anlatan istatistiksel bir kavramdır', ['Tek bir molekülün kinetik enerjisi hiçbir zaman ölçülemez', 'Oksijen molekülleri 300 K\'de gaz hâlinde bulunamaz', 'Sıcaklık yalnız katı ve sıvılar için tanımlıdır'], 'Sıcaklık, çok sayıda taneciğin enerji dağılımının ortalamasıyla ilişkilidir; tek bir taneciğin hızı çarpışmadan çarpışmaya değişir ve ona sıcaklık atfetmek anlamsızdır.'),
  ('Solunan kuru havada oksijen %21\'dir. Hava solunum yollarında 37 °C\'de su buharıyla doyuruluyor (su buharının kısmi basıncı 47 mmHg). Toplam basınç 760 mmHg ise bu nemli havadaki oksijenin kısmi basıncı yaklaşık kaç mmHg\'dir?', '150', ['160,5', '47', '713'], 'Su buharı dışındaki gazların toplam basıncı 760 − 47 = 713 mmHg\'dir; oksijenin kısmi basıncı 0,21 × 713 ≈ 150 mmHg olur.'),
  ('İdeal bir gazın iç enerjisi hangi değişkene bağlıdır?', 'Yalnız sıcaklığa', ['Yalnız basınca', 'Yalnız hacme', 'Basınç ve hacmin oranına'], 'İdeal gazda tanecikler arası etkileşim olmadığından potansiyel enerji yoktur; iç enerji yalnız kinetik enerjiye, yani sıcaklığa bağlıdır.'),
  ('Atmosferde yükseklikle basıncın azalmasına karşın küçük bir laboratuvar kabındaki gazın basıncı tabanda ve tavanda neden pratikte aynı alınır?', 'Kabın yüksekliği boyunca gazın ağırlığından doğan fark ihmal edilecek kadar küçüktür', ['Gaz molekülleri yerçekiminden hiç etkilenmez', 'Kap kapalı olduğu için yerçekimi içeriye etki etmez', 'Gaz kabın yalnız tabanında toplandığı için'], 'Gaz yoğunluğu çok küçük olduğundan birkaç santimetrelik yükseklik farkı ölçülemeyecek kadar küçük bir basınç farkı yaratır; atmosferde ise kilometrelerce sütun söz konusudur.'),
  ('Normal koşullarda 1 mol gaz 22,4 L hacim kaplar. Aynı koşullarda 1 molekülün kapladığı ortalama hacim yaklaşık kaç nm³\'tür? (Nₐ = 6,02·10²³, 1 L = 10²⁴ nm³)', '37', ['3,7', '370', '0,37'], '22,4 L = 2,24·10²⁵ nm³; bu hacim 6,02·10²³ moleküle bölünürse molekül başına yaklaşık 37 nm³ düşer; bu da yaklaşık 3,3 nm\'lik bir küp kenarına karşılık gelir.'),
  ('Normal koşullardaki 1 L gazda bulunan molekül sayısı, 1 L sıvı sudaki molekül sayısının yaklaşık kaçta biridir? (Su: 1 g/mL, 18 g/mol)', '1240', ['22,45', '55,5', '18'], '1 L suda 1000/18 ≈ 55,5 mol, 1 L gazda 1/22,4 ≈ 0,0446 mol vardır; oran 55,5/0,0446 ≈ 1240\'tır.'),
  ('İdeal gaz sabiti kalori cinsinden ifade edildiğinde yaklaşık hangi değeri alır?', '1,987 cal/(mol·K)', ['0,082 cal/(mol·K)', '8,314 cal/(mol·K)', '62,36 cal/(mol·K)'], '1 cal = 4,184 J olduğundan 8,314/4,184 ≈ 1,987 cal/(mol·K) bulunur.'),
  ('Sabit sıcaklıkta belirli miktardaki ideal gaz için ln P değerleri ln V değerlerine karşı çizilirse doğrunun eğimi kaç olur?', '−1', ['1', '0', '−1/2'], 'PV = k ise ln P = ln k − ln V olur; bu doğrunun eğimi −1\'dir.'),
  ('Pistonlu yalıtılmış bir silindirde gaz, piston dışarı doğru çekilerek hızla genleştiriliyor. Kinetik teoriye göre gazın soğumasının nedeni nedir?', 'Uzaklaşan pistona çarpan moleküllerin daha düşük hızla geri dönmesi', ['Moleküllerin genleşirken sayıca azalması', 'Pistonun moleküllerden kütle alması', 'Genleşmede moleküller arası çekimlerin artması'], 'Geri çekilen çepere çarpan bir tanecik, sabit çepere göre daha yavaş seker; toplamda gaz iş yapar, kinetik enerjisi ve sıcaklığı düşer.'),
  ('27 °C\'de su üzerinde toplanan bir gazın hacmi 100 mL ve toplam basıncı 787 mmHg\'dir. 27 °C\'de suyun buhar basıncı 27 mmHg ise kuru gazın normal koşullardaki hacmi yaklaşık kaç mL\'dir?', '91', ['100', '94', '83'], 'Kuru gazın basıncı 787 − 27 = 760 mmHg\'dir; V₀ = 100 × (760/760) × (273/300) ≈ 91 mL bulunur.'),
  ('Sabit hacimli bir kapta 100 °C\'de toplam basıncı 2 atm olan eşit mollerde N₂ ve su buharı karışımı 25 °C\'ye soğutuluyor. 25 °C\'de suyun buhar basıncı 0,031 atm ise son toplam basınç yaklaşık kaç atm olur?', '0,83', ['1,605', '0,80', '1,00'], 'N₂\'nin basıncı 1 × 298/373 ≈ 0,80 atm\'ye iner; suyun büyük kısmı yoğuşur ve buharı 0,031 atm\'de kalır. Toplam ≈ 0,83 atm.'),
  ('Kuru hava hacimce %21 O₂ içerir ve ortalama mol kütlesi yaklaşık 29 g/mol\'dür. Havadaki oksijenin kütlece yüzdesi yaklaşık kaçtır? (O₂ = 32 g/mol)', '23', ['21,5', '32', '19'], '100 mol havada 21 mol O₂ (672 g) ve toplam yaklaşık 2900 g vardır; kütle yüzdesi 672/2900 ≈ %23\'tür.'),
  ('Bir öğrenci ideal gaz denkleminde basıncı kPa, hacmi L olarak kullanıyor. Bu birimlerle uyumlu R değeri hangisidir?', '8,314 L·kPa/(mol·K)', ['0,082 L·kPa/(mol·K)', '62,4 L·kPa/(mol·K)', '1,987 L·kPa/(mol·K)'], '1 L·kPa = 10⁻³ m³ × 10³ Pa = 1 J olduğundan R = 8,314 J/(mol·K) = 8,314 L·kPa/(mol·K)\'dir.'),
  ('İdeal gaz denkleminde mol sayısı n yerine N/Nₐ (N: molekül sayısı) yazılırsa denklem hangi biçimi alır?', 'PV = NkT', ['PV = NRT', 'PV = kT/N', 'PV = NₐkT/N'], 'n = N/Nₐ ve R = Nₐ·k olduğundan nRT = (N/Nₐ)(Nₐk)T = NkT bulunur; k Boltzmann sabitidir.'),
  ('Andrews\'in CO₂ deneylerinde kritik sıcaklığın altındaki bir izoterm sıkıştırılırken basıncın bir süre sabit kaldığı yatay bir bölüm gözlenir. Bu bölüm neyi gösterir?', 'Gazın sıvılaşarak sıvı ve buharın bir arada bulunduğunu', ['Gazın kimyasal olarak bozunduğunu', 'Gazın tamamen ideal davrandığını', 'Gazın katılaştığını'], 'Yatay bölümde hacim küçüldükçe buhar sıvıya dönüşür; sıvıyla dengedeki buharın basıncı sabit kaldığından basınç değişmez.'),
  ('Kapalı bir tüpteki sıvı ve buharı kritik sıcaklığa kadar ısıtıldığında sıvı ile buhar arasındaki ayrım çizgisi (menisküs) kaybolur. Bunun nedeni nedir?', 'Sıvı ve buharın yoğunluklarının birbirine eşitlenmesi', ['Sıvının tamamen donması', 'Buharın tümüyle tüpten kaçması', 'Sıvının buharla kimyasal tepkimeye girmesi'], 'Isıtıldıkça sıvının yoğunluğu azalır, buharınki artar; kritik noktada iki faz ayırt edilemez hâle gelir ve menisküs görünmez olur.'),
  ('1 atm ve 100 °C\'deki su buharının ideal gaz denklemiyle hesaplanan hacmi ölçülen değerden biraz büyük çıkar. Bu sapmanın en iyi açıklaması hangisidir?', 'Buharın yoğuşma koşuluna çok yakın olup molekülleri arasında belirgin çekim bulunması', ['Su moleküllerinin bu sıcaklıkta parçalanması', 'Buharın ideal gazdan daha hafif olması', 'Hacim ölçümünde basıncın Kelvin cinsinden alınmaması'], 'Kaynama noktasındaki buhar sıvılaşmanın eşiğindedir; hidrojen bağı yapabilen moleküller birbirini çeker ve gaz ideal gazdan biraz daha küçük hacim kaplar.'),
  ('Üretim hatası nedeniyle kapalı uçlu bir manometrenin kapalı kolunda vakum yerine az miktarda hava kalmıştır. Bu manometreyle ölçülen gaz basıncı için ne söylenebilir?', 'Okunan seviye farkı gerçek basıncı olduğundan küçük gösterir', ['Okunan seviye farkı gerçek basıncı olduğundan büyük gösterir', 'Okunan değer atmosfer basıncına bağlı olarak değişir', 'Ölçüm hiç etkilenmez, doğru sonuç verir'], 'Gaz basıncı, seviye farkının yanında kapalı koldaki hava basıncını da karşılar; yalnız seviye farkı okunduğundan sonuç gerçek değerden küçük çıkar.'),
  ('Sodyum azürün 65 g/mol\'dür. Hava yastığında 0,4 mol NaN₃ tamamen ayrışırsa 27 °C ve 1 atm\'de yaklaşık kaç L N₂ oluşur? (2NaN₃ → 2Na + 3N₂, R = 0,082)', '14,8', ['9,8', '22,15', '32,8'], '0,4 mol NaN₃\'ten 0,6 mol N₂ çıkar; V = nRT/P = 0,6 × 0,082 × 300 / 1 ≈ 14,8 L olur.'),
  ('Gay-Lussac gözlemine göre 1 hacim H₂ ile 1 hacim Cl₂\'dan 2 hacim HCl oluşur. Avogadro\'nun yorumu bu sonuçtan hangi çıkarımı sağlamıştır?', 'Hidrojen ve klor moleküllerinin iki atomlu olduğunu', ['Klorun hidrojenden iki kat ağır olduğunu', 'HCl molekülünün tek atomlu olduğunu', 'Gazların hacminin sıcaklıktan bağımsız olduğunu'], 'Aynı sayıda molekül aynı hacmi kaplar; 1 H₂ + 1 Cl₂ → 2 HCl olması için her molekülün en az iki atom içermesi gerekir.'),
  ('Dumas yöntemiyle 250 mL\'lik bir balonda 100 °C ve 1 atm\'de buharlaşan sıvının kütlesi 0,80 g bulunmuştur. Mol kütlesi yaklaşık kaç g/mol\'dür? (R = 0,082)', '98', ['49', '196', '245'], 'M = mRT/(PV) = 0,80 × 0,082 × 373 / (1 × 0,25) ≈ 98 g/mol.'),
  ('Sabit hacimde kapalı kaptaki gazın sıcaklığı 27 °C\'den 54 °C\'ye çıkarılıyor. Basınç için hangisi doğrudur?', 'Yaklaşık %9 artar', ['İki katına çıkar', 'Yaklaşık %50 artar', 'Değişmez'], 'Mutlak sıcaklık 300 K\'den 327 K\'e çıktığından basınç 327/300 ≈ 1,09 kat olur; Celsius değerleri oranlanamaz.'),
  ('27 °C\'de 24,6 L\'lik kapta 2 atm basınç yapan ideal gazda yaklaşık kaç tane molekül vardır? (R = 0,082; N_A = 6,02 × 10²³)', '1,2 × 10²⁴', ['6,0 × 10²³', '2,4 × 10²⁴', '1,2 × 10²³'], 'n = PV/RT = 2 × 24,6 / (0,082 × 300) = 2 mol; molekül sayısı 2 × 6,02 × 10²³ ≈ 1,2 × 10²⁴ olur.'),
  ('Derin dalışta mutlak basıncın 5 atm olduğu 40 m derinlikte, oksijenin kısmi basıncını 1,6 atm\'i aşmayacak biçimde sınırlamak için solunan karışımda O₂ en çok hacimce yüzde kaç olmalıdır?', '32', ['16', '21', '40'], 'Kısmi basınç = mol kesri × toplam basınç olduğundan en çok 1,6 / 5 = 0,32, yani %32 O₂ kullanılabilir.'),
  ('Dış ortam 20 °C, balon içi 100 °C ve 1 atm\'dedir; balon zarfı 2800 m³, havanın ortalama mol kütlesi 29 g/mol alınırsa balonun net kaldırma kütlesi yaklaşık kaç kg olur? (R = 8,314 J/(mol·K))', '720', ['260', '1200', '3400'], 'd = PM/RT ile dış hava 1,206 kg/m³, iç hava 0,948 kg/m³ bulunur; fark 0,258 kg/m³ × 2800 m³ ≈ 720 kg yapar.'),
  ('Sabit sıcaklıkta ideal bir gazın yoğunluğunun basınca karşı grafiğinde doğrunun eğimi nedir?', 'M/(RT)', ['RT/M', 'M·RT', 'P/M'], 'd = PM/(RT) olduğundan d–P grafiği orijinden geçen bir doğrudur ve eğimi M/(RT)\'dir.'),
  ('Van der Waals denkleminde a = 0 ve b = 0,04 L/mol alınırsa, 300 K\'de 1 L\'lik kapta 1 mol gazın basıncı ideal değerinden yaklaşık kaç atm fazla çıkar? (R = 0,082)', '1,0', ['0,04', '0,5', '2,0'], 'Gerçek P = nRT/(V − nb) = 24,6/0,96 ≈ 25,6 atm; ideal değer 24,6 atm olduğundan fark yaklaşık 1,0 atm\'dir.'),
  ('Sürtünmesiz bir pistonlu kapta 2 mol ideal gaz, sabit dış basınçta 50 K ısıtılıp genleşiyor. Gazın piston üzerinde yaptığı iş yaklaşık kaç J\'dür? (R = 8,314 J/(mol·K))', '831', ['416', '1247', '16 628'], 'Sabit basınçta iş w = PΔV = nRΔT = 2 × 8,314 × 50 ≈ 831 J\'dür.'),
  ('Joule–Thomson genleşmesinde oda sıcaklığındaki helyum gazının davranışı nasıldır?', 'Isınır, çünkü inversiyon sıcaklığı oda sıcaklığının altındadır', ['Soğur, çünkü tüm gazlar genleşirken soğur', 'Sıcaklığı hiç değişmez', 'Önce yoğunlaşır, sonra donar'], 'Helyumun inversiyon sıcaklığı çok düşüktür; oda sıcaklığında genleşirken ısınır, soğuması için önce inversiyon sıcaklığının altına soğutulmalıdır.'),
  ('Bir ucu kapalı, düşey bir cam borunun kapalı ucunda 20 cm uzunluğunda hava, üstünde 10 cm\'lik cıva sütunu bulunuyor (açık uç yukarıda, P₀ = 76 cmHg). Boru açık ucu aşağı gelecek biçimde ters çevrilirse, cıva dökülmediği ve sıcaklık sabit kaldığı varsayımıyla hava sütununun uzunluğu yaklaşık kaç cm olur?', '26,1', ['20,0', '23,2', '30,0'], 'İlk basınç 76 + 10 = 86 cmHg, sonraki 76 − 10 = 66 cmHg\'dir; L₂ = 86 × 20 / 66 ≈ 26,1 cm.'),
  ('Yatayda 40 cm hava sütununu 19 cm\'lik cıva ile kapatan boru, açık ucu aşağı bakacak biçimde dik tutuluyor ve cıva dökülmüyor. Hava sütunu yaklaşık kaç cm olur? (P₀ = 76 cmHg)', '53,3', ['30,0', '46,5', '57,0'], 'Dikte hapsedilen havanın basıncı 76 − 19 = 57 cmHg\'ye düşer; L = 76 × 40 / 57 ≈ 53,3 cm.'),
  ('60 kg kütleli bir kişinin ağırlığı (g = 10 m/s²) tamamen 1 cm²\'lik bir topuk ucuna binerse zemine uygulanan basınç yaklaşık kaç atm olur?', '59', ['0,6', '6', '590'], 'P = 600 N / 10⁻⁴ m² = 6 × 10⁶ Pa; bu değer 101 325 Pa\'ya bölünürse yaklaşık 59 atm bulunur.'),
  ('Su dolu, ucu açık bir manometrede gaz tarafındaki su seviyesi açık koldakinden 34 cm aşağıdadır. Atmosfer basıncı 760 mmHg ise gaz basıncı yaklaşık kaç mmHg\'dir? (d_cıva = 13,6 g/cm³, d_su = 1 g/cm³)', '785', ['760', '794', '1100'], '340 mm su sütunu 340/13,6 = 25 mmHg eder; gaz tarafı aşağıda olduğundan basınç 760 + 25 = 785 mmHg olur.'),
  ('Yoğunluğu 0,8 g/cm³ olan yağ dolu ucu açık bir manometrede gaz tarafındaki sıvı seviyesi açık koldakinden 17 cm yukarıdadır. Atmosfer basıncı 760 mmHg ise gaz basıncı kaç mmHg\'dir? (d_cıva = 13,6 g/cm³)', '750', ['743', '757', '777'], '170 mm yağ = 170 × 0,8 / 13,6 = 10 mmHg eder; gaz tarafı yukarıda olduğundan basınç 760 − 10 = 750 mmHg\'dir.'),
  ('Normal koşullarda yoğunluğu yaklaşık 1,61 g/L olan N₂–CO₂ karışımında CO₂\'nin mol kesri kaçtır? (N₂: 28, CO₂: 44 g/mol)', '0,5', ['0,25', '0,40', '0,75'], 'M_ort = 1,61 × 22,4 ≈ 36 g/mol; 28(1 − x) + 44x = 36 denkleminden x = 0,5 bulunur.'),
  ('Kütlece eşit miktarda He (4 g/mol) ve CH₄ (16 g/mol) içeren karışımın toplam basıncı 5 atm ise He\'nin kısmi basıncı kaç atm\'dir?', '4', ['2,5', '3,5', '4,5'], 'Örneğin 16 g\'dan 4 mol He ve 1 mol CH₄ vardır; He\'nin mol kesri 0,8 olduğundan kısmi basıncı 0,8 × 5 = 4 atm\'dir.'),
  ('10 L\'lik bir tüpte 120 atm basınçta sıkıştırılmış hava vardır. Sıcaklık sabitken tüpteki basınç 1 atm\'e düşene kadar gaz, 5 L\'lik ve 1 atm\'lik balonlara aktarılırsa kaç balon doldurulabilir?', '238', ['120', '240', '1190'], 'Toplam kullanılabilir gaz (120 − 1) × 10 = 1190 L·atm olup 1 atm\'de 1190 L eder; 1190/5 = 238 balon dolar.'),
  ('CO₂\'nin kritik sıcaklığı 31 °C, kritik basıncı yaklaşık 73 atm\'dir. 40 °C\'de ve 100 atm\'de CO₂ hangi halde bulunur?', 'Süperkritik akışkan', ['Katı', 'Sıvı–gaz dengesinde karışım', 'Normal sıvı'], 'Sıcaklık kritik sıcaklığın üstünde olduğundan basınç ne kadar artırılsa da sıvı–gaz ayrımı oluşmaz; madde süperkritik akışkandır.'),
  ('25 °C\'de su üzerinde toplanan 200 mL O₂\'nin toplam basıncı 744 mmHg\'dir ve 25 °C\'de suyun buhar basıncı 24 mmHg\'dir. Kuru O₂\'nin mol sayısı yaklaşık kaçtır? (R = 0,082 L·atm/(mol·K))', '7,75 × 10⁻³', ['7,5 × 10⁻³', '8,0 × 10⁻³', '1,0 × 10⁻²'], 'P(O₂) = 744 − 24 = 720 mmHg = 0,947 atm; n = PV/RT = 0,947 × 0,2 / (0,082 × 298) ≈ 7,75 × 10⁻³ mol.'),
  ('25 °C\'deki 10 L\'lik bir odada bağıl nem %50\'dir ve bu sıcaklıkta doygun su buharı basıncı 24 mmHg\'dir. Odadaki su buharının kütlesi yaklaşık kaç gramdır? (H₂O = 18 g/mol, R = 0,082 L·atm/(mol·K))', '0,116', ['0,058', '0,230', '1,16'], 'P = 0,5 × 24 = 12 mmHg = 0,0158 atm; n = PV/RT ≈ 0,00646 mol olup kütle 0,00646 × 18 ≈ 0,116 g bulunur.'),
  ('Bir hava yastığını 27 °C ve 1 atm\'de 60 L N₂ ile şişirmek için yaklaşık kaç gram NaN₃ (65 g/mol) gerekir? (2NaN₃ → 2Na + 3N₂; R = 0,082)', '106', ['71', '159', '211'], 'n(N₂) = 60/24,6 ≈ 2,44 mol; n(NaN₃) = 2/3 × 2,44 ≈ 1,63 mol ve kütle 1,63 × 65 ≈ 106 g\'dır.'),
  ('İç hacmi 2 L olan bir bisiklet lastiği 1 atm\'de hava ile doludur. Her vuruşta 0,1 L ve 1 atm\'lik hava lastiğe pompalanıyor. Sıcaklık ve lastik hacmi sabit kabul edilirse lastikteki mutlak basıncı 3 atm yapmak için kaç vuruş gerekir?', '40', ['20', '60', '13,3'], 'Gerekli toplam PV = 3 × 2 = 6 L·atm, başlangıçta 2 L·atm vardır; eksik 4 L·atm, her vuruşta 0,1 L·atm ile 40 vuruşta tamamlanır.'),
  ('Hacmi 12 L olan dalış tüpü 200 atm\'e doldurulmuş ve içinde 50 atm basınç emniyet payı olarak kalmalıdır. Dalgıç yüzeyde dakikada 20 L (1 atm eşdeğeri) soluyorsa 3 atm mutlak basınçlı derinlikte yaklaşık kaç dakika kalabilir?', '30', ['20', '45', '90'], 'Kullanılabilir gaz (200 − 50) × 12 = 1800 L (1 atm\'de); 3 atm\'de tüketim 3 × 20 = 60 L/dk olduğundan süre 1800/60 = 30 dakikadır.'),
  ('Yoğunluğu 1,26 g/cm³ olan gliserinle Torricelli barometresi yapılsaydı, 760 mmHg\'lik atmosfer basıncında sıvı sütunu yaklaşık kaç metre yüksekliğe çıkardı? (d_cıva = 13,6 g/cm³)', '8,2', ['0,76', '10,3', '13,6'], 'Sütun yüksekliği yoğunlukla ters orantılıdır: h = 0,76 m × 13,6 / 1,26 ≈ 8,2 m.'),
  ('Kesit alanı 2 cm² olan ucu kapalı bir şırıngada 20 mL hava 1 atm\'dedir. Piston sabit sıcaklıkta 5 mL\'ye itilirse pistona dıştan ek olarak yaklaşık kaç N kuvvet uygulanması gerekir? (1 atm = 101 325 Pa)', '61', ['20', '30', '243'], 'Basınç 4 atm olur; içeri-dışı fark 3 atm = 304 kPa\'dır ve F = ΔP × A = 304 000 × 2 × 10⁻⁴ ≈ 61 N bulunur.'),
  ('Hacmi sabit bir odadaki hava sabit basınçta 27 °C\'den 57 °C\'ye ısıtılırken oda açık olduğu için bir kısmı dışarı çıkıyor. Başlangıçtaki havanın yüzde kaçı odadan çıkar?', '9,1', ['5,3', '10,0', '30,0'], 'Sabit P ve V\'de n ∝ 1/T\'dir; n₂/n₁ = 300/330 olduğundan çıkan oran 30/330 ≈ %9,1\'dir.'),
  ('27 °C ve 1 atm\'de kapağı kapatılan 50 cm² kesitli bir kavanoz, içindeki hava 127 °C\'ye ısıtılıyor. Dış basınç 1 atm kalırsa kapağı kaldırmaya çalışan net kuvvet yaklaşık kaç N olur? (1 atm = 101 325 Pa)', '169', ['34', '85', '507'], 'Sabit hacimde P₂ = 1 × 400/300 = 4/3 atm; fark 1/3 atm ≈ 33 775 Pa ve F = ΔP × A = 33 775 × 0,005 ≈ 169 N\'dur.'),
  ('Aynı hacimde helyum ile hidrojen dolu balonların net kaldırma kuvveti karşılaştırılırsa (hava 29, H₂ 2, He 4 g/mol), helyum balonu hidrojenli balonun yaklaşık yüzde kaçı kadar kaldırır?', '93', ['50', '75', '100'], 'Aynı koşulda 1 mol için kaldırma: H₂ ile 29 − 2 = 27 g, He ile 29 − 4 = 25 g; oran 25/27 ≈ %93\'tür.'),
  ('Kuru havanın hacimce %78 azot içerdiği ve ortalama mol kütlesinin 28,96 g/mol olduğu bilindiğine göre, havanın kütlece yaklaşık yüzde kaçı azottur? (N₂ = 28 g/mol)', '75', ['60', '78', '82'], '1 mol havada 0,78 × 28 = 21,84 g azot vardır; kütle yüzdesi 21,84/28,96 ≈ %75\'tir.'),
  ('Hidrojene göre bağıl yoğunluğu 11,5 olan CH₄ (16 g/mol) – C₂H₆ (30 g/mol) karışımında CH₄\'ün mol kesri kaçtır?', '0,5', ['0,25', '0,6', '0,75'], 'M_ort = 11,5 × 2 = 23 g/mol; 16x + 30(1 − x) = 23 denkleminden x = 0,5 bulunur.'),
  ('Dayanıklı bir tüpün içindeki havanın bir pistonla çok hızlı sıkıştırılması kimi ateş yakma düzeneklerinde içerideki kalın bir pamuk parçasını tutuşturabilir. Bu olayın nedeni nedir?', 'Hızlı sıkıştırılan gaz ısı kaçıramadığı için sıcaklığı çok yükselir', ['Gazın sıkışırken basıncının azalması', 'Pistonun sürtünmeyle gazı kimyasal olarak ayrıştırması', 'Havadaki azotun hızla yanması'], 'Sıkıştırma çok hızlıysa ısı çevreye iletilemez; piston gaz moleküllerine enerji aktarır ve gazın sıcaklığı tutuşma noktasına çıkar.'),
];
